var t=`0931-turnip-cake`;var n=`world-0931`;var a=`CN`;var o=`east-asia`;var s=8;var r=95;var l={en:`Turnip Cake`,ua:`Рисовий пиріг із дайконом`};var d={en:`Turnip Cake is a China dish made with daikon, dried shrimp powder, shiitake mushroom, rice flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Рисовий пиріг із дайконом, страва кухні країни Китай. Основні складники: дайкон, порошок із сушених креветок, шиїтаке, рисове борошно. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:15,i:[[`daikon`,700,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`dried-shrimp-powder`,70,`g`],[`shiitake-mushroom`,100,`g`],[`canola-oil`,30,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`rice-flour`,235,`g`],[`cornstarch`,45,`g`],[`water`,240,`ml`],[`table-salt`,5,`g`]]},{en:`Steam the daikon and rice-flour mixture in a well-oiled deep mold until completely set; let it cool enough to slice.`,ua:`Пропарте суміш дайкона та рисового борошна в добре змащеній глибокій формі до повного застигання; остудіть, щоб нарізати.`,t:[`steaming`],m:45,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`canola-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`light-soy-sauce`,40,`ml`]]}];var m={slug:t,id:n,country:`CN`,region:o,servings:8,minutes:95,title:l,text:d,steps:u};export{a as country,m as default,n as id,r as minutes,o as region,s as servings,t as slug,u as steps,d as text,l as title};